style.css:
@-moz-document domain("discord.com") {
body, 
    [class*="appMount_"], 
    [class*="bg_"], 
    [class*="chat_"], 
    [class*="chatContent_"] {
        color: rgb(94, 87, 78) !important;
        font-family: "Times New Roman", serif !important;
        background-image: url("https://i.pinimg.com/1200x/b5/ec/4c/b5ec4c661b472d47aa8ff8424dd79d05.jpg") !important;
        background-repeat: no-repeat !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    [class*="mainContent_"],
    [class*="pageWrapper_"],
    [class*="container_"],
    [class*="panels_"] {
        background: transparent !important;
    }

    [class*="sidebar_"] {
        width: 375px !important;
        height: 100vh !important;
        background-image: url("https://i.pinimg.com/1200x/3c/99/71/3c9971b9c24729871684c2869efbdcb5.jpg") !important;
        background-repeat: no-repeat !important;
        background-size: cover !important;
        background-position: center !important;
        box-shadow: 0px 0px 10px 5px rgba(109, 79, 79, 0.849) !important;
    }
}
